#include <stdio.h>
#include <string.h>

int main(int argc, char *argv[]) {
    // No strings provided (only program name)
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }
    // Too many arguments (including program name)
    if (argc > 0x41) { // 65 in decimal
        puts("TOO_MANY");
        return 0;
    }
    // Verify each argument length does not exceed 1024 characters
    for (int i = 1; i < argc; ++i) {
        if (strlen(argv[i]) > 0x400) { // 1024 in decimal
            puts("TOO_LONG");
            return 0;
        }
    }
    // Compute longest common prefix among all arguments (excluding program name)
    const char *first = argv[1];
    size_t prefix_len = strlen(first);
    for (int i = 2; i < argc; ++i) {
        size_t j = 0;
        while (j < prefix_len && first[j] && argv[i][j] && first[j] == argv[i][j]) {
            ++j;
        }
        prefix_len = j;
        if (prefix_len == 0) {
            break;
        }
    }
    // Output the prefix followed by a newline
    for (size_t i = 0; i < prefix_len; ++i) {
        putchar(first[i]);
    }
    putchar('\n');
    return 0;
}
